// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Run tracked-section scrape (cron)
	// (POST /admin/scrape-sections)
	AdminScrapeSections(ctx context.Context, request AdminScrapeSectionsRequestObject) (AdminScrapeSectionsResponseObject, error)
	// Rebuild course index (cron)
	// (POST /admin/update-index)
	AdminUpdateIndex(ctx context.Context, request AdminUpdateIndexRequestObject) (AdminUpdateIndexResponseObject, error)
	// Login
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Register
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// Log out (invalidate token)
	// (DELETE /auth/session)
	DeleteSession(ctx context.Context, request DeleteSessionRequestObject) (DeleteSessionResponseObject, error)
	// List sections from the index
	// (GET /courses)
	ListCourses(ctx context.Context, request ListCoursesRequestObject) (ListCoursesResponseObject, error)
	// Batch live occupancy
	// (POST /courses/occupancy)
	PostCoursesOccupancy(ctx context.Context, request PostCoursesOccupancyRequestObject) (PostCoursesOccupancyResponseObject, error)
	// Autocomplete suggestions
	// (GET /courses/suggestions)
	ListCourseSuggestions(ctx context.Context, request ListCourseSuggestionsRequestObject) (ListCourseSuggestionsResponseObject, error)
	// Live section by CRN
	// (GET /courses/{crn})
	GetCourseByCrn(ctx context.Context, request GetCourseByCrnRequestObject) (GetCourseByCrnResponseObject, error)
	// Service analytics
	// (GET /stats)
	GetStats(ctx context.Context, request GetStatsRequestObject) (GetStatsResponseObject, error)
	// Delete account
	// (DELETE /users/me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// Current user
	// (GET /users/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Update profile / notification preferences
	// (PATCH /users/me)
	PatchMe(ctx context.Context, request PatchMeRequestObject) (PatchMeResponseObject, error)
	// List tracked sections
	// (GET /users/me/sections)
	ListMySections(ctx context.Context, request ListMySectionsRequestObject) (ListMySectionsResponseObject, error)
	// Track a section
	// (POST /users/me/sections)
	AddMySection(ctx context.Context, request AddMySectionRequestObject) (AddMySectionResponseObject, error)
	// Stop tracking a section
	// (DELETE /users/me/sections/{crn})
	DeleteMySection(ctx context.Context, request DeleteMySectionRequestObject) (DeleteMySectionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

